<template>
  <div class="w-full relative">
    <!-- Splash Screen（场景切换由墨迹转场覆盖，无需额外淡入淡出） -->
    <SplashScreen
      v-if="appState === 'SPLASH'"
      key="splash"
      :environment-report="environmentReport"
      :environment-checking="isEnvironmentChecking"
      :suppress-environment-panel="isStartingGame"
      @start="startGame"
      @force-start="forceStartGame"
      @check-environment="checkEnvironment()"
      @toggle-fullscreen="toggleFullScreen"
      @open-collection="isCollectionOpen = true"
      @open-tutorial="startTutorialTraining"
      @background-change="splashBackgroundUrl = $event"
    />

    <!-- Game -->
    <GameView
      v-else
      key="game"
      :show-opening-entry="isOpeningEntryOpen"
      :opening-entry-background-url="splashBackgroundUrl"
      :opening-entry-loading="isOpeningEntrySubmitting"
      :opening-entry-error="openingEntryError"
      @back-to-splash="handleBackToSplash"
      @submit-opening-entry="handleOpeningEntrySubmit"
    />
    <WitchCollectionModal :is-open="isCollectionOpen" @close="isCollectionOpen = false" />
    <TutorialBattleView v-if="isTutorialBattleOpen" @close="closeTutorialBattle" />
    <SceneTransitionOverlay />
  </div>
</template>

<script setup lang="ts">
import { ensureAuthorTestAccessBenefits } from './authorTestAccess';
import GameView from './components/GameView.vue';
import SceneTransitionOverlay from './components/SceneTransitionOverlay.vue';
import SplashScreen from './components/SplashScreen.vue';
import TutorialBattleView from './components/TutorialBattleView.vue';
import WitchCollectionModal from './components/WitchCollectionModal.vue';
import { disposeBgm, initializeBgm } from './bgm';
import { disposeSfx, initializeSfx } from './sfx';
import { runEnvironmentCheck, type EnvironmentCheckReport } from './environmentCheck';
import { toggleFullScreen } from './fullscreen';
import { useGameStore } from './gameStore';
import { buildOpeningPrompt, type OpeningInfoSubmission } from './openingProfile';
import { runSceneTransition } from './sceneTransition';

const appState = ref<'SPLASH' | 'GAME'>('SPLASH');
const isCollectionOpen = ref(false);
const isTutorialBattleOpen = ref(false);
const isOpeningEntryOpen = ref(false);
const isOpeningEntrySubmitting = ref(false);
const isEnvironmentChecking = ref(false);
const isStartingGame = ref(false);
const openingEntryError = ref<string | null>(null);
const splashBackgroundUrl = ref('');
const environmentReport = ref<EnvironmentCheckReport | null>(null);
const gameStore = useGameStore();

function startTutorialTraining() {
  void runSceneTransition(() => {
    isTutorialBattleOpen.value = true;
  });
}

function closeTutorialBattle() {
  void runSceneTransition(() => {
    isTutorialBattleOpen.value = false;
  });
}

onMounted(() => {
  ensureAuthorTestAccessBenefits();
  void initializeBgm();
  initializeSfx();
});

onUnmounted(() => {
  disposeBgm();
  disposeSfx();
});

/**
 * 开始游戏：初始化 gameStore（加载最新楼层状态、MVU）
 */
async function startGame() {
  if (isEnvironmentChecking.value) return;

  isStartingGame.value = true;
  try {
    const report = await checkEnvironment({ notifyFailure: true });
    if (!report.ready) return;

    environmentReport.value = null;
    await enterGame();
  } finally {
    isStartingGame.value = false;
  }
}

async function forceStartGame() {
  if (isEnvironmentChecking.value) return;

  toastr.warning('已跳过环境检测，若依赖缺失可能导致游戏异常。', '无视风险开始');
  await enterGame();
}

async function enterGame() {
  // 墨迹覆盖后再切换并加载楼层状态；加载期间停在全黑帧
  await runSceneTransition(async () => {
    appState.value = 'GAME';
    isOpeningEntryOpen.value = false;
    isOpeningEntrySubmitting.value = false;
    openingEntryError.value = null;
    await nextTick();
    await gameStore.initialize();
    isOpeningEntryOpen.value = gameStore.isFreshChatSession();
  });
}

function handleBackToSplash() {
  void runSceneTransition(() => {
    isOpeningEntryOpen.value = false;
    isOpeningEntrySubmitting.value = false;
    openingEntryError.value = null;
    appState.value = 'SPLASH';
  });
}

async function checkEnvironment(options: { notifyFailure?: boolean } = {}) {
  if (isEnvironmentChecking.value && environmentReport.value) {
    return environmentReport.value;
  }

  isEnvironmentChecking.value = true;
  try {
    const report = await runEnvironmentCheck();
    environmentReport.value = report;
    if (!report.ready && options.notifyFailure) {
      toastr.error(report.summary, '环境未就绪');
    }
    return report;
  } finally {
    isEnvironmentChecking.value = false;
  }
}

async function handleOpeningEntrySubmit(payload: OpeningInfoSubmission) {
  if (isOpeningEntrySubmitting.value) return;

  isOpeningEntrySubmitting.value = true;
  openingEntryError.value = null;

  try {
    const roleProfile = {
      种族: payload.race,
      姓名: payload.name,
      年龄: payload.age,
      贞操: payload.chastity,
      天赋: payload.talent,
      外貌: payload.appearance,
      特征: payload.traits,
      身高: payload.heightCm,
      体重: payload.weightType,
      胸围: payload.bust,
      臀部: payload.hips,
      小穴: payload.vagina,
      屁穴: payload.anus,
      敏感点: payload.sensitivePoints,
      背景故事: payload.backstory,
    };

    const openingProfileFields = {
      主角信息: roleProfile,
    };

    await gameStore.updateStatDataFields(openingProfileFields);
    gameStore.setPendingStatDataChanges(openingProfileFields);

    await gameStore.sendAction(buildOpeningPrompt(payload));
    if (gameStore.error) {
      openingEntryError.value = gameStore.error;
      return;
    }

    isOpeningEntryOpen.value = false;
  } catch (err) {
    openingEntryError.value = err instanceof Error ? err.message : String(err);
  } finally {
    isOpeningEntrySubmitting.value = false;
  }
}
</script>
