  const task = (async () => {
    const url = await resolveCharacterPortraitUrl(characterName);
    if (bondPortraitLoaderDisposed) return;
    try {
      await preloadImage(url);
    } catch {
      if (!bondPortraitLoaderDisposed) {
        bondPortraitErrors.value = {
          ...bondPortraitErrors.value,
          [characterName]: true,
        };
