      return;
    }
    if (bondPortraitLoaderDisposed) return;
    bondPortraitUrls.value = {
      ...bondPortraitUrls.value,
      [characterName]: url,
    };
    bondPortraitErrors.value = {
      ...bondPortraitErrors.value,
      [characterName]: false,
