    next.push(influence);
  }

  next = ensureCustomDifficultyBase(next);
  isUpdatingMagicHatDifficulty.value = true;
  const ok = await gameStore.updateStatDataFields({
    $难度: '自定义',
    $自定义影响: next,
  });
