    chestRewardCollectedFlags,
    chestCollecting,
    chestRewardVisible,
    chestOpenedBgReady,
    chestRewardCountFixed,
    chestCloseCount,
    chestForceMimicNextOpen,
    shopProducts,
    shopSpentGold,
    shopPurchasedItems,
    shopRobClickCount,
    shopRobbing,
    idolVariant,
    idolDiceValue,
    idolDiceTwoValue,
    idolDiceRolling,
    idolAssignedTarget,
    idolDiceTwoAssignedTarget,
    idolSnapPreviewTarget,
    idolDiceTwoSnapPreviewTarget,
    idolDicePosition,
    idolDiceTwoPosition,
    victoryRewardStage,
    victoryRewardOptions,
    selectedVictoryRewardCard,
    mimicRelicDropRelic,
    mimicRelicDropApplying,
    rewardRefreshUsedCount,
    rewardIsNormalEnemy,
